package com.sshop.entity;
import com.baomidou.mybatisplus.annotation.*; import lombok.Data; import java.math.BigDecimal; import java.time.LocalDateTime;
@Data @TableName("cs_goods") public class Goods { @TableId("goods_id") private Long goodsId; @TableField("goods_name") private String goodsName; @TableField("goods_price") private BigDecimal goodsPrice; @TableField("goods_stock") private Integer goodsStock; @TableField("goods_cover") private String goodsCover; @TableField("goods_status") private Integer goodsStatus; @TableField("goods_sort") private Integer goodsSort; @TableField("goods_remark") private String goodsRemark; @TableField("create_time") private LocalDateTime createTime; @TableField("update_time") private LocalDateTime updateTime; @TableField("del_flag") private Integer delFlag; }
